import { useState } from "react";

import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { createServerFn } from "@tanstack/react-start";
import { eq } from "drizzle-orm";

import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { db } from "@/lib/db";
import { inviteCodes } from "@/lib/db/schema";
import {
  type ValidationResult,
  validateInviteCode,
} from "@/lib/invite-code-validation";

import { SignUpButton } from "./-components/sign-up-button";

const validateInviteCodeServer = createServerFn({ method: "GET" })
  .inputValidator((code: unknown) => {
    if (typeof code !== "string" || !code) {
      throw new Error("Invite code must be a string");
    }
    return code;
  })
  .handler(async ({ data: code }): Promise<ValidationResult> => {
    const inviteCodeRecords = await db
      .select({
        code: inviteCodes.code,
        used_by: inviteCodes.used_by,
        revoked_at: inviteCodes.revoked_at,
      })
      .from(inviteCodes)
      .where(eq(inviteCodes.code, code));

    return validateInviteCode(code, inviteCodeRecords);
  });

export const Route = createFileRoute("/sign-up")({
  validateSearch: (search): { code?: string } => ({
    code: typeof search.code === "string" ? search.code : undefined,
  }),
  loaderDeps: ({ search }) => ({ code: search.code }),
  loader: async ({ deps }): Promise<ValidationResult> => {
    if (!deps.code) {
      return { valid: false, error: "Invite code is required" };
    }
    return await validateInviteCodeServer({ data: deps.code });
  },
  component: SignUpPage,
});

function InviteCodeForm() {
  const [value, setValue] = useState("");
  const navigate = useNavigate();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = value.trim();
    if (!trimmed) return;
    navigate({ to: "/sign-up", search: { code: trimmed } });
  };

  return (
    <div className="flex min-h-screen items-center justify-center">
      <Card className="w-full max-w-sm">
        <CardHeader>
          <CardTitle>Invites are required (for now)</CardTitle>
          <CardDescription>
            If you received an invite code, enter it below.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            <div className="flex flex-col gap-2">
              <Label htmlFor="invite-code" className="sr-only">
                Invite Code
              </Label>
              <Input
                id="invite-code"
                type="text"
                placeholder="Enter your invite code"
                value={value}
                onChange={(e) => setValue(e.target.value)}
              />
            </div>
            <Button type="submit" disabled={!value.trim()}>
              {value.trim() ? "CONTINUE" : "CODE REQUIRED"}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

function SignUpPage() {
  const { code } = Route.useSearch();
  const result = Route.useLoaderData();

  if (!result.valid) {
    return <InviteCodeForm />;
  }

  return (
    <div className="flex min-h-screen items-center justify-center">
      <div className="flex flex-col items-center gap-4">
        <h2 className="text-lg font-medium text-foreground">
          Create your account
        </h2>
        <SignUpButton code={code ?? ""} />
      </div>
    </div>
  );
}
import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { admin } from "better-auth/plugins/admin";
import { tanstackStartCookies } from "better-auth/tanstack-start";
import { and, eq, isNull } from "drizzle-orm";

import { db } from "@/lib/db";
import {
  accounts,
  chickenSightings,
  inviteCodes,
  sessions,
  stores,
  users,
  verifications,
} from "@/lib/db/schema";
import { env } from "@/lib/env";
import { getBaseURL, INVITE_CODE_COOKIE_RE } from "@/lib/utils/auth";

export const auth = betterAuth({
  database: drizzleAdapter(db, {
    provider: "pg",
    usePlural: true,
    schema: {
      users,
      sessions,
      accounts,
      verifications,
      stores,
      inviteCodes,
      chickenSightings,
    },
  }),
  secret: env.BETTER_AUTH_SECRET,
  baseURL: getBaseURL(),
  socialProviders: {
    google: {
      clientId: env.GOOGLE_CLIENT_ID,
      clientSecret: env.GOOGLE_CLIENT_SECRET,
    },
  },
  user: {
    additionalFields: {
      default_store_id: {
        type: "number",
        input: false,
      },
      commute_minutes: {
        type: "number",
        input: false,
      },
      trust_score: {
        type: "string",
        input: false,
      },
    },
  },
  databaseHooks: {
    user: {
      create: {
        before: async (user, ctx) => {
          const cookieHeader = ctx?.headers?.get("cookie") ?? "";
          const match = INVITE_CODE_COOKIE_RE.exec(cookieHeader);
          const code = match?.[1];

          if (!code) {
            throw new Error("Invite code is required to sign up");
          }

          const [inviteCode] = await db
            .select()
            .from(inviteCodes)
            .where(
              and(
                eq(inviteCodes.code, code),
                isNull(inviteCodes.used_by),
                isNull(inviteCodes.revoked_at)
              )
            )
            .limit(1);

          if (!inviteCode) {
            throw new Error("Invalid or already used invite code");
          }

          return { data: user };
        },
        after: async (user, ctx) => {
          const cookieHeader = ctx?.headers?.get("cookie") ?? "";
          const match = INVITE_CODE_COOKIE_RE.exec(cookieHeader);
          const code = match?.[1];

          if (code) {
            await db
              .update(inviteCodes)
              .set({
                used_by: user.id,
                used_at: new Date(),
              })
              .where(eq(inviteCodes.code, code));
          }
        },
      },
    },
  },
  plugins: [admin(), tanstackStartCookies()],
});
import { createServerFn } from "@tanstack/react-start";
import { getRequestHeaders } from "@tanstack/react-start/server";

import { auth } from "@/lib/auth";

export const getSession = createServerFn({ method: "GET" }).handler(
  async () => {
    const headers = getRequestHeaders();
    const session = await auth.api.getSession({ headers });
    return session;
  }
);

export const ensureSession = createServerFn({ method: "GET" }).handler(
  async () => {
    const headers = getRequestHeaders();
    const session = await auth.api.getSession({ headers });
    if (!session) {
      throw new Error("Unauthorized");
    }
    return session;
  }
);
